/**
 *
 * DataTableSelection exposes selection state and callbacks via render prop,
 * allowing users to compose their own selection UI (checkbox, radio, switch, etc.).
 * Automatically detects header vs row context.
 *
 * [Live Demo](https://www.primereact.org/datatable/)
 *
 * @module DataTableSelection
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { UseDataTableSelectionEvent } from '@primereact/types/headless/datatable';
import * as React from 'react';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { DataTableRootInstance } from './DataTableRoot.types';
/**
 * Defines passthrough(pt) options type in DataTableSelection component.
 */
export type DataTableSelectionPassThroughType<E> = PassThroughType<DataTableSelectionInstance, E>;
/**
 * Defines passthrough(pt) options of DataTableSelection component.
 */
export interface DataTableSelectionPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: DataTableSelectionPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
}
/**
 * Defines valid properties in DataTableSelection component.
 */
export interface DataTableSelectionProps extends BaseComponentProps<DataTableSelectionInstance, unknown, DataTableSelectionPassThrough> {
    /**
     * Override the toggle mode for row selection.
     * - 'radio': select only one row, no deselect on re-click.
     * - 'checkbox': toggle individual rows.
     * - 'single': select one row, deselect on re-click.
     * When not set, defaults to 'single' for selectionMode="single" and 'checkbox' for selectionMode="multiple".
     */
    mode?: 'radio' | 'checkbox' | 'single';
}
/**
 * Defines valid state in DataTableSelection component.
 */
export interface DataTableSelectionState {
}
/**
 * Defines the methods and properties exposed by DataTableSelection component.
 * Rendered once per row and once per header cell; inspect `isHeader` to pick the right fields.
 */
export interface DataTableSelectionExposes {
    /**
     * The DataTable component instance.
     */
    datatable: DataTableRootInstance | undefined | null;
    /**
     * True when the component is rendered inside a header cell (select-all context).
     */
    isHeader: boolean;
    /**
     * True when **all** rows are selected. Meaningful only in header context.
     */
    isAllSelected: boolean;
    /**
     * True when **some** rows (but not all) are selected. Meaningful only in header context.
     */
    isSomeSelected: boolean;
    /**
     * Select or deselect every row. Meaningful only in header context.
     */
    toggleAll: (event: React.SyntheticEvent) => void;
    /**
     * True when the current row is selected. Meaningful only in row context.
     */
    isSelected: boolean;
    /**
     * True when the current row is partially selected (tree selection tri-state).
     * Meaningful only in row context.
     */
    isPartiallySelected: boolean;
    /**
     * Toggle selection for the current row. Meaningful only in row context.
     */
    toggle: (event: React.SyntheticEvent) => void;
}
/**
 * Instance of DataTableSelection component.
 */
export type DataTableSelectionInstance = ComponentInstance<DataTableSelectionProps, DataTableSelectionState, DataTableSelectionExposes>;
/**
 * Event re-exported from the headless layer so consumers can import it from the
 * primitive/UI barrel instead of reaching into headless. Mirrors `UseDataTableSelectionEvent`.
 */
export interface DataTableSelectionEvent extends UseDataTableSelectionEvent {
}
